$plants$::jsonb) AS source(
  code text,clean_name text,diameter_cm integer,group_key text,merge_eligible boolean
);
ALTER TABLE imported_plant_normalization ADD PRIMARY KEY(code);

DO $validate$
BEGIN
  IF (SELECT COUNT(*) FROM imported_plant_normalization) <> 281 THEN
    RAISE EXCEPTION 'expected 281 positive-stock plant codes';
  END IF;
  IF EXISTS (SELECT 1 FROM imported_plant_normalization WHERE clean_name='' OR code='') THEN
    RAISE EXCEPTION 'plant normalization contains an empty identity';
  END IF;
END;
$validate$;

CREATE TEMP TABLE resolved_imported_plants ON COMMIT DROP AS
SELECT source.*,product.id AS product_id,
       ((product.latin_name<>'')::int + (product.short_description<>'')::int +
        (product.description<>'')::int + (product.care_instructions<>'')::int +
        EXISTS(SELECT 1 FROM product_media media WHERE media.product_id=product.id)::int) AS content_score
FROM imported_plant_normalization source
JOIN LATERAL (
  SELECT candidate.*
  FROM products candidate
  LEFT JOIN saby_nomenclature linked ON linked.saby_id=candidate.saby_id
  WHERE candidate.status='draft'
    AND candidate.catalog_section='plants'
    AND (
      UPPER(BTRIM(linked.code))=source.code OR
      EXISTS(SELECT 1 FROM product_external_ids external
             WHERE external.product_id=candidate.id AND external.provider='saby'
               AND external.id_type='code' AND UPPER(BTRIM(external.external_id))=source.code)
    )
    AND NOT EXISTS(SELECT 1 FROM order_items item WHERE item.product_id=candidate.id)
    AND NOT EXISTS(SELECT 1 FROM product_reviews review WHERE review.product_id=candidate.id)
  ORDER BY candidate.id
  LIMIT 1
) product ON TRUE;

UPDATE product_variants variant
SET label=CASE WHEN resolved.diameter_cm IS NOT NULL AND variant.label='Основной вариант'
               THEN 'D'||resolved.diameter_cm ELSE variant.label END,
    pot_diameter_cm=COALESCE(variant.pot_diameter_cm,resolved.diameter_cm),
    updated_at=CURRENT_TIMESTAMP
FROM resolved_imported_plants resolved
WHERE variant.product_id=resolved.product_id;

UPDATE products product
SET name=resolved.clean_name,search_text=resolved.clean_name,updated_at=CURRENT_TIMESTAMP
FROM resolved_imported_plants resolved
WHERE product.id=resolved.product_id AND product.name IS DISTINCT FROM resolved.clean_name;

DO $merge$
DECLARE
  group_row record;
  source_id bigint;
  source_variant bigint;
BEGIN
  FOR group_row IN
    SELECT group_key,
      (array_agg(product_id ORDER BY content_score DESC,product_id))[1] AS target_id,
      array_agg(product_id ORDER BY product_id) AS product_ids
    FROM resolved_imported_plants
    WHERE merge_eligible
    GROUP BY group_key
    HAVING COUNT(DISTINCT product_id)>1
  LOOP
    FOREACH source_id IN ARRAY group_row.product_ids LOOP
      IF source_id=group_row.target_id THEN CONTINUE; END IF;

      SELECT id INTO source_variant FROM product_variants
      WHERE product_id=source_id ORDER BY is_active DESC,id LIMIT 1;

      INSERT INTO product_attribute_values(product_id,attribute_id,value,source,updated_at)
      SELECT group_row.target_id,attribute_id,value,source,CURRENT_TIMESTAMP
      FROM product_attribute_values WHERE product_id=source_id
      ON CONFLICT(product_id,attribute_id) DO NOTHING;

      INSERT INTO collection_products(collection_id,product_id,sort_order)
      SELECT collection_id,group_row.target_id,sort_order
      FROM collection_products WHERE product_id=source_id
      ON CONFLICT DO NOTHING;

      UPDATE product_variants SET product_id=group_row.target_id,updated_at=CURRENT_TIMESTAMP
      WHERE product_id=source_id;
      UPDATE product_external_ids
      SET product_id=group_row.target_id,
          variant_id=COALESCE(variant_id,source_variant),
          updated_at=CURRENT_TIMESTAMP
      WHERE product_id=source_id;
      UPDATE product_media SET product_id=group_row.target_id WHERE product_id=source_id;
      DELETE FROM products WHERE id=source_id;
    END LOOP;
  END LOOP;
END;
$merge$;

INSERT INTO admin_audit_log(actor_customer_id,actor_role,action,entity_type,entity_id,after_data)
VALUES(NULL,'system','catalogue.import.normalize','catalogue','positive-plants',
       jsonb_build_object(
         'sourceCodes',(SELECT COUNT(*) FROM imported_plant_normalization),
         'resolvedDrafts',(SELECT COUNT(*) FROM resolved_imported_plants),
         'mergeGroups',(SELECT COUNT(*) FROM (
           SELECT group_key FROM resolved_imported_plants WHERE merge_eligible
           GROUP BY group_key HAVING COUNT(DISTINCT product_id)>1
         ) grouped)
       ));
